"""The Excel file generated by src/export/excel_exporter.py opens with openpyxl
and contains, at least, the SUM and HIST sheets."""
import openpyxl

from export.excel_exporter import build_workbook
from processing.classifier import classify_batch


def test_workbook_has_sum_and_hist_sheets(seeded_db, tmp_path):
    output_path = str(tmp_path / "export.xlsx")

    build_workbook(seeded_db, output_path)

    wb = openpyxl.load_workbook(output_path)
    assert "SUM" in wb.sheetnames
    assert "HIST" in wb.sheetnames
    # Per-country sheet of the seeded run (US).
    assert "US" in wb.sheetnames


def test_workbook_country_sheet_excludes_evident_homonym(seeded_db, tmp_path):
    """2.3: a result marked same_person='no' must not appear on the
    per-country sheet (nor contaminate the "OWN URLs" matrix in SUM)."""
    results = classify_batch([
        {"domain": "scam.example", "url": "https://scam.example/excel-homonym",
         "title": "Excel homonym item", "description": "", "country_code": "us"},
    ])
    results[0]["same_person"] = "no"
    seeded_db.save_run(apify_run_id="r-excel-homonym", queries=["q"], country_code="us",
                       status="completed",
                       summary={"total": 1, "positive": 0, "negative": 1, "neutral": 0})
    seeded_db.save_results(results, run_id="r-excel-homonym")
    output_path = str(tmp_path / "export2.xlsx")

    build_workbook(seeded_db, output_path)

    wb = openpyxl.load_workbook(output_path)
    ws = wb["US"]
    cell_values = [c.value for row in ws.iter_rows() for c in row]
    assert "https://scam.example/excel-homonym" not in cell_values
